@verbatim
<template id="finance-users-template">
<section v-if="view.name==='users'" class="panel users-panel"><div class="section-heading"><div><h2>Користувачі кабінету</h2><p>Прив’яжіть Telegram вручну або відкрийте бота за одноразовим посиланням.</p></div><label class="search-field"><icon name="search"></icon><input v-model="userSearch" type="search" placeholder="Знайти користувача…" aria-label="Знайти користувача"></label></div><div class="users-grid"><article v-for="member in members" :key="member.id" class="user-card"><div class="user-card-heading"><span class="avatar">{{(member.name||member.email||'?').charAt(0).toUpperCase()}}</span><div><h3>{{member.name||'Користувач'}}<span v-if="member.is_self" class="user-self-label">Ви</span></h3><p>{{member.email}}</p><small>ID користувача: {{member.id}}</small></div></div><div :class="['telegram-status',{connected:member.telegram_id}]"><icon name="telegram"></icon><div><strong>{{member.telegram_id?'Telegram прив’язаний':'Telegram не прив’язаний'}}</strong><span>{{member.telegram_id?'ID: '+member.telegram_id:'Статистика та нові витрати просто в чаті'}}</span></div></div><label class="telegram-notifications"><input type="checkbox" :checked="member.telegram_notifications_enabled" :disabled="notificationsSaving[member.id]||!member.telegram_chat_connected" @change="toggleTelegramNotifications(member,$event)"><span><strong>Отримувати повідомлення від бота</strong><small>{{member.telegram_chat_connected?'Сповіщати про нові транзакції':'Спочатку відкрийте бота й натисніть «Старт»'}}</small></span></label><div class="user-card-actions"><button class="button outlined" :disabled="saving" @click="openDialog('userTelegram',member)"><icon name="edit"></icon>{{member.telegram_id?'Змінити Telegram ID':'Ввести Telegram ID'}}</button><button class="button primary" :disabled="linking" @click="openTelegram(member)"><icon name="telegram"></icon>Відкрити Telegram-бота</button></div></article></div><div v-if="!members.length" class="empty-state"><icon name="users"></icon><h3>Нікого не знайдено</h3><p>Спробуйте інший пошуковий запит.</p></div><p class="users-help">Посилання діє 10 хвилин. Відкрийте Telegram і натисніть «Старт» — бот автоматично прив’яже акаунт. Статус оновиться після повернення в кабінет.</p><button class="button text" :disabled="loading" @click="load"><icon name="refresh"></icon>Оновити список</button></section>
</template>
@endverbatim
